import java.io.*;
import java.util.*;

public class vanyaandscale {
    public static void main(String[] arg) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (w <= 3) {
            System.out.println("YES");
            return;
        }

        long limit = 100000000000L;
        long[] a = new long[40];
        a[0] = 1L;
        long temp = 1L;
        int n = 1;

        while (n < 16) {
            temp *= w;
            a[n] = temp;
            if (temp > limit) break;
            n++;
        }

        Set<Long> balances = new HashSet<>();
        balances.add(0L);

        for (int i = 0; i < n; i++) {
            Set<Long> next = new HashSet<>();
            for (long v : balances) {
                next.add(v);
                next.add(v + a[i]);
                next.add(v - a[i]);
            }
            balances = next;
        }

        System.out.println(balances.contains(m) ? "YES" : "NO");
    }
}
